def list_existing_subjects(apps, schema_editor):
    BaselinePending = apps.get_model("notifications", "BaselinePending")
    Host = apps.get_model("hosts", "Host")
    Cluster = apps.get_model("clusters", "Cluster")
    Network = apps.get_model("network", "Network")
    hosts = Host.objects.filter(latest_report__isnull=False).values_list("pk", flat=True)
    clusters = Cluster.objects.filter(latest_snapshot__isnull=False).values_list("pk", flat=True)
    networks = Network.objects.exclude(status="waiting").values_list("pk", flat=True)
    BaselinePending.objects.bulk_create(
        [BaselinePending(host_id=pk) for pk in hosts]
        + [BaselinePending(cluster_id=pk) for pk in clusters]
        + [BaselinePending(network_id=pk) for pk in networks]
    )


